 q=c['questions'][0]
 c['questions'].append({**q,'id':c['id']+'-recall','prompt':c['recall'],'choices':[],'answer':0,'explanation':c['recallAnswer'],'difficulty':1,'type':'recall','distractors':[]})
 if 'formula' in c:
  formula=c['formula']; others=[x['formula']['expression'] for x in records if 'formula' in x and x['id']!=c['id']][:2]
  c['questions'].append({**q,'id':c['id']+'-formula','prompt':'Reconstruct the relationship for '+formula['name'].lower()+'. Write it from memory, then reveal and compare.','choices':[],'answer':0,'explanation':formula['expression']+'\n'+formula['variables'],'difficulty':2,'type':'formula','distractors':[]})
